text:
tabbox {
  color: inherit;
  text-shadow: none;
}

tabs {
  margin-block: 8px 10px;
  margin-inline: 4px;
  border-block-end-color: var(--box-border-color);
}

tab {
  border-block-end-width: 2px;

  &:hover {
    background-color: var(--tab-hover-background);
  }

  &[visuallyselected] {
    background-color: var(--tab-selected-background);
    border-block-end-color: var(--lwt-tab-line-color, var(--tabline-color));
  }
}

tabpanels {
  appearance: none;
  border: none;
  padding: 0;
  background-color: transparent;
  color: inherit;
}
